param([Parameter(Mandatory=$true)][string]$Version,[Parameter(Mandatory=$true)][string]$Artifact,[Parameter(Mandatory=$true)][string]$Signature,[Parameter(Mandatory=$true)][string]$Repository)
$ErrorActionPreference="Stop";$name=Split-Path $Artifact -Leaf;$hash=(Get-FileHash $Artifact -Algorithm SHA256).Hash.ToLower();$size=(Get-Item $Artifact).Length;$sig=(Get-Content $Signature -Raw).Trim();$manifest=[ordered]@{version=$Version;channel="stable";publishedAt=(Get-Date).ToUniversalTime().ToString("o");releaseNotes="Release $Version";minSupportedVersion="1.0.0";platform="windows-x86_64";url="https://github.com/$Repository/releases/download/v$Version/$name";sha256=$hash;signature=$sig;size=$size;mandatory=$false};$manifest|ConvertTo-Json|Set-Content manifest-go.json -Encoding utf8
